import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In the first quadrant, an {rows} by {cols} array of congruent circles of diameter {diameter} is packed so that their centers form a rectangular lattice with horizontal and vertical spacing equal to the diameter. The southwest-most center is at ({x_offset}, {y_offset}). The circle at the southwest corner and the circle at the northeast corner are removed. Let R be the union of the remaining circles. For the fixed slope {slope_p}/{slope_q}, there is a unique line l of that slope that bisects the area of R. Its equation can be written in the form ax = by + c, where a, b, and c are positive integers with gcd(a, b, c) = 1. Find a^2 + b^2 + c^2.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate an odd-by-odd grid of circles with lattice spacing = diameter.
# Remove SW and NE corners to preserve central symmetry. Choose slope a/b coprime.
# Ensure c = a*h - b*k > 0 by controlling y_offset.
def coprime_pair(lo_a=2, hi_a=9, lo_b=1, hi_b=9):
    import math
    for _ in range(100):
        a = rng.randint(lo_a, hi_a)
        b = rng.randint(lo_b, hi_b)
        if math.gcd(a, b) == 1:
            return a, b
    return 3, 1  # fallback

import math
for _ in range(200):
    rows = rng.choice([3,5,7,9])
    cols = rng.choice([3,5,7,9])
    diameter = rng.randint(1, 6)
    x_offset = rng.randint(1, 8)
    slope_p, slope_q = coprime_pair()
    # Compute center (h,k) of full array (and of the symmetric union after removals)
    h = x_offset + diameter * ((rows - 1) // 2)
    # We will choose y_offset so that c > 0. c = a*h - b*k where k = y_offset + diameter * ((cols-1)//2)
    # So we need: a*h - b*(y_offset + midy) > 0 => y_offset < (a*h)/b - midy
    midy = diameter * ((cols - 1) // 2)
    # Compute upper bound for y_offset ensuring c>=1 (strictly positive)
    ub = math.floor((slope_p * h - slope_q * midy - 1) / slope_q)
    if ub >= 1:
        y_offset = rng.randint(1, min(ub, 8))
    else:
        continue  # retry if cannot satisfy c>0 with this configuration
    # Sanity check c>0
    k = y_offset + midy
    c_val = slope_p * h - slope_q * k
    if c_val <= 0:
        continue
    # Construct and return assignment
    return {
        'rows': rows,
        'cols': cols,
        'diameter': diameter,
        'x_offset': x_offset,
        'y_offset': y_offset,
        'slope_p': slope_p,
        'slope_q': slope_q
    }
# Fallback safe assignment if retries fail (rare)
return {
    'rows': 5,
    'cols': 3,
    'diameter': 2,
    'x_offset': 5,
    'y_offset': 1,
    'slope_p': 3,
    'slope_q': 1
}

    def verifier(assign):
# Verify domain constraints and compute the answer.
# The key fact used: If a region is centrally symmetric about a point (h,k), then any line through (h,k) bisects its area.
# Our construction (odd-by-odd grid with SW and NE removed) is centrally symmetric about the midpoint of the full grid.
import math
# Extract
try:
    rows = int(assign['rows'])
    cols = int(assign['cols'])
    diameter = int(assign['diameter'])
    x0 = int(assign['x_offset'])
    y0 = int(assign['y_offset'])
    a = int(assign['slope_p'])
    b = int(assign['slope_q'])
except Exception:
    return (False, None)  # malformed
# Basic validity
if rows % 2 != 1 or cols % 2 != 1 or rows < 3 or cols < 3:
    return (False, None)  # must be odd >=3
if diameter <= 0 or x0 <= 0 or y0 <= 0:
    return (False, None)
if a <= 0 or b <= 0 or math.gcd(a, b) != 1:
    return (False, None)
# Compute center (h,k)
h = x0 + diameter * ((rows - 1) // 2)
k = y0 + diameter * ((cols - 1) // 2)
# Build centers set with SW and NE removed
centers = set()
for i in range(rows):
    for j in range(cols):
        if (i == 0 and j == 0) or (i == rows - 1 and j == cols - 1):
            continue  # remove SW and NE
        xi = x0 + i * diameter
        yj = y0 + j * diameter
        centers.add((xi, yj))
# Check central symmetry: for each center (x,y), the rotated point (2h-x, 2k-y) must be in the set
for (x, y) in centers:
    sx = 2 * h - x
    sy = 2 * k - y
    if (sx, sy) not in centers:
        # If symmetry fails, our bisector claim would not hold
        return (False, None)
# Compute c and ensure positivity (to match problem statement)
c = a * h - b * k
if c <= 0:
    return (False, None)
# gcd(a,b,c) must be 1; since gcd(a,b)=1, this holds automatically unless c shares a common factor with both (which is impossible)
if math.gcd(math.gcd(a, b), c) != 1:
    return (False, None)
# Answer: a^2 + b^2 + c^2
answer = a*a + b*b + c*c
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

